import time

def retry_with_backoff(fn, max_attempts=3):
    """Call `fn` up to `max_attempts` times, retrying on exception with
    exponential back‑off.  On the final failure the exception is re‑raised
    immediately (no sleep)."""
    attempt = 0
    while attempt < max_attempts:
        try:
            return fn()
        except Exception:
            attempt += 1
            if attempt == max_attempts:
                raise
            # Simple linear back‑off; increase the wait with each retry
            time.sleep(0.01 * attempt)
