from freight import shipping_cost

def total_with_shipping(subtotal, weight_kg):
    """
    Return the total cost including shipping, rounded to two decimal places.

    Shipping is free for any order with a subtotal of $50 or more.
    For subtotals below $50, the freight module calculates the shipping cost.
    """
    if subtotal >= 50:
        return round(subtotal, 2)
    return round(subtotal + shipping_cost(subtotal, weight_kg), 2)
